const body = $input.first().json.body || $input.first().json;
const bodyStr = JSON.stringify(body).substring(0,300);
const d = body.data || body;
const key = d.key || body.key || {};
const fromMe = key.fromMe === true;
const remoteJid = key.remoteJid || '';
const isLid = remoteJid.includes('@lid');
const clientId = remoteJid.replace(/@\S+/,'');

function normalizarTelefone(valor) {
  if (!valor) return '';
  let t = valor.replace(/\D/g, '');
  t = t.replace(/^(55){2,}/, '55');
  t = t.replace(/^1(55)/, '$1');
  t = t.replace(/^(55)1(5\d{8,9})$/, '$1$2');
  if (!t.startsWith('55')) t = '55' + t;
  if (t.length === 14 && t[4] === '9') {
    t = t.substring(0,4) + t.substring(5);
  }
  return t;
}

let telefone;
if (isLid) {
  const sender = body.sender 
    || d.sender 
    || body.data?.sender
    || $input.first().json.sender
    || $input.first().json.body?.sender
    || '';
  if (sender) {
    telefone = normalizarTelefone(sender.replace(/@\S+/,''));
  } else {
    telefone = 'lid_' + clientId;
  }
} else {
  telefone = normalizarTelefone(clientId);
}

const pushName = d.pushName || body.pushName || '';
const msg = d.message || body.message || {};
const mensagem = (msg.conversation || msg.extendedTextMessage?.text || '').trim();

if (fromMe || !clientId || !mensagem) {
  return [{ json: { ignorar: true, debug_telefone: telefone, debug_mensagem: mensagem, debug_body: bodyStr }}];
}

const hora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false }) * 1;
const saudacao = hora < 12 ? 'Bom dia' : hora < 18 ? 'Boa tarde' : 'Boa noite';

return [{ json: { 
  telefone, 
  clientId,
  isLid,
  mensagem, 
  mensagem_lower: mensagem.toLowerCase(), 
  pushName, 
  saudacao, 
  hora, 
  ignorar: false,
  debug_sender: body.sender || d.sender || $input.first().json.sender || 'NAO_ENCONTRADO'
}}];

const sessao = $input.first().json[0] || {};
const estado = sessao.estado || 'novo';
const nome_salvo = sessao.nome || '';
const dados = typeof sessao.dados === 'string' ? JSON.parse(sessao.dados || '{}') : (sessao.dados || {});

const ctx = $('Normalizar Payload').first().json;
const pushName = ctx.pushName || '';

// Nome: prioridade 1 = banco, 2 = pushName do WhatsApp
const nome = nome_salvo || pushName || '';
const primeiro_nome = nome.split(' ')[0] || '';

return [{
  json: {
    ...ctx,
    estado,
    dados,
    nome,
    primeiro_nome,
    cliente_novo: estado === 'novo' || !estado
  }
}];

const telefone = $('Normalizar Payload').first().json.telefone;
const sessao = $('Buscar Sessão').first().json;
const nome = sessao?.nome || 'cliente';
const msgIndex = parseInt(sessao?.msg_index) || 1;

const hora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false }) * 1;
let saudacao;
if (hora >= 5 && hora < 12) saudacao = `Bom dia, ${nome}!`;
else if (hora >= 12 && hora < 18) saudacao = `Boa tarde, ${nome}!`;
else saudacao = `Boa noite, ${nome}!`;

const APP = 'https://zensalon.com.br';

const mensagens = {
  1: `${saudacao} 😊 Que bom ter você aqui!

Agendar com a gente é super fácil e rápido. Acesse nosso app e escolha o melhor horário pra você.

👉 ${APP}

Te esperamos! 💜`,
  2: `${saudacao} ✨ Ficamos felizes com sua mensagem!

Você pode agendar seu horário diretamente pelo nosso aplicativo, sem filas e sem espera.

📱 ${APP}

Estamos prontos pra te receber!`,
  3: `${saudacao} 🌸 Obrigada por entrar em contato!

Para marcar seu atendimento é só acessar o link abaixo. Rápido, fácil e sem complicação.

🔗 ${APP}

Nos vemos em breve! 😉`,
  4: `${saudacao} 💅 Que bom falar com você!

Seu próximo momento de beleza está a um clique. Acesse o app e escolha data, horário e serviço.

👉 ${APP}

Vamos te esperar com tudo preparado! 🌟`,
  5: `${saudacao} 😍 Tudo certo por aqui!

Para garantir seu horário sem risco de perder a vaga, acesse nosso aplicativo agora.

📲 ${APP}

Agenda rápida, atendimento com carinho! 💜`,
  6: `${saudacao} 🎉 Que alegria receber sua mensagem!

Faça seu agendamento online pelo nosso app — disponível 24 horas, você agenda na hora que quiser.

🔗 ${APP}

Te esperamos com um sorriso! 😊`,
  7: `${saudacao} 🌺 Obrigada por nos procurar!

No nosso aplicativo você escolhe o serviço, a profissional e o horário ideal pra você — tudo de forma prática.

👉 ${APP}

Até logo! 💜`,
  8: `${saudacao} ⭐ É um prazer falar com você!

Não perca seu horário preferido. Acesse agora o app e garanta sua vaga em poucos segundos.

📱 ${APP}

Qualquer dúvida, é só chamar! 😉`,
  9: `${saudacao} 🌷 Olá, que bom ter você aqui!

Agende seu atendimento de forma rápida e sem complicação pelo nosso aplicativo.

🔗 ${APP}

Nos vemos em breve, tá? 💜`
};

const proximoIndex = (msgIndex % 9) + 1;

return [{
  json: {
    telefone,
    mensagem_resposta: mensagens[msgIndex],
    proximo_msg_index: proximoIndex
  }
}];

const { mensagem_lower, telefone, primeiro_nome, saudacao } = $input.first().json;

// Palavras que indicam intenção de agendar
const palavras_agendamento = [
  'agendar', 'marcar', 'horário', 'horario', 'quero marcar', 'quero agendar',
  'escova', 'corte', 'unha', 'coloração', 'coloracao', 'progressiva',
  'sobrancelha', 'manicure', 'pedicure', 'depilação', 'depilacao',
  'hidratação', 'hidratacao', 'botox', 'mechas', 'luzes', 'pintura',
  'quero', 'preciso', 'gostaria', 'pode', 'consegue', 'tem vaga',
  'tem horario', 'tem horário', 'disponivel', 'disponível'
];

// Palavras que indicam problema/dificuldade
const palavras_problema = [
  'não consigo', 'nao consigo', 'não abre', 'nao abre', 'erro',
  'problema', 'ajuda', 'não funciona', 'nao funciona', 'não sei',
  'nao sei', 'como', 'como faz', 'como faço'
];

// Palavras de endereço
const palavras_endereco = [
  'endereço', 'endereco', 'onde fica', 'localização', 'localizacao',
  'onde vocês', 'onde voces', 'como chegar', 'mapa'
];

// Palavras de horário de funcionamento
const palavras_horario = [
  'horário de funcionamento', 'horario de funcionamento',
  'que horas', 'abre', 'fecha', 'funcionamento', 'aberto'
];

// Palavras de preço
const palavras_preco = [
  'preço', 'preco', 'valor', 'quanto custa', 'quanto fica',
  'tabela', 'valores', 'preços', 'precos'
];

// Palavras de telefone
const palavras_telefone = ['telefone', 'numero', 'número', 'ligar', 'contato'];

// Palavras de agradecimento
const palavras_agradecimento = ['obrigada', 'obrigado', 'valeu', 'brigada', 'brigado', 'thanks', 'grata'];

const quer_agendar = palavras_agendamento.some(p => mensagem_lower.includes(p));
const tem_problema = palavras_problema.some(p => mensagem_lower.includes(p));
const quer_endereco = palavras_endereco.some(p => mensagem_lower.includes(p));
const quer_horario = palavras_horario.some(p => mensagem_lower.includes(p));
const quer_preco = palavras_preco.some(p => mensagem_lower.includes(p));
const quer_telefone = palavras_telefone.some(p => mensagem_lower.includes(p));
const agradecendo = palavras_agradecimento.some(p => mensagem_lower.includes(p));

let mensagem_resposta = '';
let novo_estado = 'aguardando_resposta';

if (agradecendo) {
  mensagem_resposta = 'Eu que agradeço. 😊\n\nEsperamos você em breve. 💜';
  novo_estado = 'encerrado';
} else if (quer_endereco) {
  mensagem_resposta = 'Estamos localizados em:\n\n📍 {{ENDERECO}}\n\nMapa: {{LINK_MAPA}}';
} else if (quer_horario) {
  mensagem_resposta = 'Funcionamos:\n\nSegunda a Sexta\n08:00 às 18:00\n\nSábado\n08:00 às 14:00';
} else if (quer_telefone) {
  mensagem_resposta = '📞 {{TELEFONE}}';
} else if (quer_preco) {
  mensagem_resposta = 'Os valores podem variar conforme o profissional e o serviço.\n\nTodos os preços atualizados estão disponíveis no aplicativo.\n\n👉 https://zensalon.com.br';
} else if (tem_problema) {
  mensagem_resposta = 'Sem problemas 😊\n\nPosso ajudar. O que aconteceu?\n\n1️⃣ Não consigo abrir\n2️⃣ Não sei usar\n3️⃣ Outro problema';
  novo_estado = 'aguardando_problema';
} else if (quer_agendar) {
  const variacoes = [
    'Perfeito 😊',
    'Ótimo 😊',
    'Claro 😊'
  ];
  const v = variacoes[Math.floor(Math.random() * variacoes.length)];
  mensagem_resposta = `${v}\n\nVocê pode escolher o profissional, serviço, dia e horário diretamente pelo aplicativo.\n\n👉 https://zensalon.com.br`;
  novo_estado = 'link_enviado';
} else {
  // Qualquer outra mensagem
  mensagem_resposta = 'Posso ajudar você a realizar seu agendamento.\n\n👉 https://zensalon.com.br';
}

return [{ json: { telefone, mensagem_resposta, novo_estado } }];
